asyncFills['offtaker-profile-fill'] = async () => {
  const s = await loadSettings();
  const nm = s.name || (isLiveMode() ? liveUserName() : 'Miller Ticharwa');
  const ph = s.phone || (isLiveMode() ? '' : '+263 77 555 1234');
  return `${field('Full name', input(nm, undefined, { val: 'oName' }))}
    ${field('Phone', input(ph, 'e.g. +263 77 555 1234', { val: 'oPhone' }))}`;
};

asyncFills['offtaker-company-fill'] = async () => {
  const s = await loadSettings();
  const co = s.company || (isLiveMode() ? '' : 'Miller Corporation');
  const reg = s.registration || (isLiveMode() ? '' : 'ZC/2024/1187');
  const addr = s.address || (isLiveMode() ? '' : 'Harare · Msasa Industrial');
  return `${field('Company', input(co, 'e.g. Miller Corporation', { val: 'ofCompany' }))}
    ${field('Registration', input(reg, 'e.g. ZC/2024/1187', { val: 'ofReg' }))}
    ${field('Address', input(addr, 'e.g. Msasa Industrial, Harare', { val: 'ofAddr' }))}`;
};

asyncFills['offtaker-pay-fill'] = async () => {
  const s = await loadSettings();
  const pay = s.payment || (isLiveMode() ? '' : 'Ecobank · 0415-2030-1187');
  const tax = s.tax || (isLiveMode() ? '' : 'ZW-7784-009');
  return `${field('Bank / Mobile money', input(pay, 'e.g. Bank or EcoCash line', { val: 'ofPay' }))}
    ${field('Tax number', input(tax, 'e.g. ZW-XXXX-XXX', { val: 'ofTax' }))}`;
};

asyncFills['offtaker-prefs-fill'] = async () => {
  const s = await loadSettings();
  return prefsPanel({ p: 'o', submit: 'of-prefs', lang: s.language, cur: s.currency, email: s.notifyEmail !== 'off', sms: s.notifySms !== 'off' });
};

onValidSubmit('of-profile', (form) => {
  void saveProfile({ name: formValue(form, 'oName'), phone: formValue(form, 'oPhone') }).then((r) => {
    restoreSubmit(form);
    if (r.ok) toast('Profile updated');
    else toast(r.error || 'Could not save profile', 'error');
  });
});

onValidSubmit('of-company', (form) => {
  void saveSettings({
    company: formValue(form, 'ofCompany'),
    registration: formValue(form, 'ofReg'),
    address: formValue(form, 'ofAddr'),
  }).then((r) => {
    restoreSubmit(form);
    if (r.ok) toast('Company details saved');
    else toast(r.error || 'Could not save company details', 'error');
  });
});

onValidSubmit('of-settings', (form) => {
  void saveSettings({ payment: formValue(form, 'ofPay'), tax: formValue(form, 'ofTax') }).then((r) => {
    restoreSubmit(form);
    if (r.ok) toast('Payout details saved');
    else toast(r.error || 'Could not save payout details', 'error');
  });
});

onValidSubmit('of-prefs', (form) => {
  void saveSettings({
    language: formValue(form, 'oLang'),
    currency: formValue(form, 'oCur'),
    notifyEmail: radioValue(form, 'oNEmail'),
    notifySms: radioValue(form, 'oNSms'),
  }).then((r) => {
    restoreSubmit(form);
    if (r.ok) toast('Preferences saved');
    else toast(r.error || 'Could not save preferences', 'error');
  });
});

onValidSubmit('of-security', (form) => {
  const pws = [...form.querySelectorAll<HTMLInputElement>('input[type="password"]')];
  if (pws[1] && pws[1].value !== pws[0]?.value) {
    toast('Passwords do not match', 'error');
    restoreSubmit(form);
    return;
  }
  void changePassword(pws[0]?.value || '').then((r) => {
    restoreSubmit(form);
    if (r.ok) toast('Password updated — use it to sign in next time');
    else toast(r.error || 'Could not update password', 'error');
  });
});
